// Protocol keys: they ride in the request but are NOT params of any command.
// ONE list, here, with the evidence for each entry. A key that IS a real param
// of the command (`type` for spawn_actor, `command` for execute_console_command,
// `force` for start_play_in_editor) is matched against the command's known set
// FIRST, so listing it here never hides it.
// ---------------------------------------------------------------------------
static const TCHAR* const GProtocolKeys[] =
{
    // sub-command envelope key of `execute_batch` items and of
    //   build_blueprint_graph nodes (UEAgentMetaCommands.cpp HandleBatch)
    TEXT("command_type"),
    // alternative spelling of the command name used by hand-written callers
    TEXT("command"),
    // per-sub-command correlation id in the documented payload shape {"id":...,
    //   "command_type":..., "params":{...}}
    TEXT("id"),
    // CROSS-CUTTING dispatcher param read for EVERY command by
    //   McpCollateralDirty::ShouldTrack (UEAgentBridge.cpp); it is in no command's
    //   catalog entry, so without this line it would be a false positive on every
    //   call that opts into collateral tracking
    TEXT("track_collateral_dirty"),
    // CROSS-CUTTING dispatcher param: the override valve of BOTH PIE gates --
    //   CheckPIEOwnershipGuard (start_/stop_play_in_editor, where `force` IS a
    //   catalogued param and so is matched there FIRST) and CheckPIESafetyGuard,
    //   which reads it on any command listed in McpPieSafety.gen.h. Without this
    //   line every forced compile/save would also report force as an unknown
    //   param, which is how a field earns being ignored
    TEXT("force"),
};

